FORMS = [
    ("రూట్ కెనాల్ చికిత్సకు సమ్మతి (Root canal, Telugu)", "endodontic", _ENDODONTIC),
    ("నోటి మరియు మాక్సిల్లో ఫేషియల్ శస్త్రచికిత్స మరియు అనస్థీషియా కొరకు సమ్మతి (Oral surgery, Telugu)", "surgical", _ORAL_SURGERY),
    ("ఆర్థోడాంటిక్ చికిత్సకు సమ్మతి (Orthodontic, Telugu)", "ortho", _ORTHODONTIC),
    ("పీరియోడాంటల్ చికిత్స సమ్మతి పత్రం (Periodontal surgery, Telugu)", "periodontal", _PERIODONTAL),
    ("ప్రోస్టోడాంటిక్ చికిత్సకు సమ్మతి (Prosthodontic, Telugu)", "prosthodontic", _PROSTHODONTIC),
    ("పీడియాట్రిక్ దంత చికిత్స సమ్మతి (Paediatric, Telugu)", "paediatric", _PAEDIATRIC),
]


def main(argv):
    email = argv[argv.index("--email") + 1].strip().lower()
    apply = "--apply" in argv

    from database import SessionLocal
    from models import Clinic, ConsentTemplate, User
    from sqlalchemy import func

    db = SessionLocal()
    try:
        user = db.query(User).filter(func.lower(User.email) == email).first()
        if not user or not user.clinic_id:
            print(f"No user with a clinic for {email}")
            return 1
        clinic = db.query(Clinic).filter(Clinic.id == user.clinic_id).first()
        print(f"{email}: user {user.id} ({user.role}), clinic {clinic.id} '{clinic.name}'")

        existing = {
            (n or "").strip().lower()
            for (n,) in db.query(ConsentTemplate.name).filter(ConsentTemplate.clinic_id == clinic.id)
        }
        print(f"clinic already has {len(existing)} consent templates")
        added = 0
        for name, category, content in FORMS:
            if name.strip().lower() in existing:
                print(f"  skip (exists): {name}")
                continue
            print(f"  {'add' if apply else 'would add'}: {name} [{category}] {len(content.splitlines())} paragraphs")
            if apply:
                db.add(ConsentTemplate(clinic_id=clinic.id, name=name, category=category,
                                       content=content, is_active=True))
            added += 1
        if apply:
            db.commit()
        print(f"{'added' if apply else 'dry run, would add'} {added}")
        return 0
    finally:
        db.close()


if __name__ == "__main__":
    sys.exit(main(sys.argv))
